import json
p='/app/benchmark/source_data.json'
data=json.load(open(p))
for sec in ['architecture_nodes','architecture_edges','governance_controls','transformation_summary']:
    print('\n'+sec.upper())
    for r in data[sec]['data']:
        if sec=='architecture_nodes': print(r['node_id'], r['label'], r['layer'], r['category'], r['daily_volume_gb'], r['format'], sep=' | ')
        elif sec=='architecture_edges': print(r['edge_id'], r['source'], '->', r['target'], r['volume_gb'], r['mode'], r['latency'], sep=' | ')
        elif sec=='governance_controls': print(r['control_id'], r['layer'], r['control_type'], r['tool'], r['enforcement'], sep=' | ')
        else: print(r['layer'], r['transformation_type'], r['count'], r['complexity'], sep=' | ')
